create function pg_temp.report(days int default 30, grade int default null) returns jsonb language sql as $$select public.learning_progress('00000000-0000-4000-8000-000000003621',days,null,grade)$$;
select is((pg_temp.report()->'summary'->>'total')::int,9,'total is evidence based');
select is((pg_temp.report()->'summary'->>'unique_questions')::int,8,'unique_questions is evidence based');
select is((pg_temp.report()->'summary'->>'repeats')::int,1,'repeats is evidence based');
select is((pg_temp.report()->'summary'->>'attempts')::int,2,'attempts is evidence based');
select is((pg_temp.report()->'summary'->>'pending')::int,1,'pending is evidence based');
select is((pg_temp.report()->'summary'->>'correct')::int,5,'correct is evidence based');
select is((pg_temp.report()->'summary'->>'partial')::int,1,'partial is evidence based');
select is((pg_temp.report()->'summary'->>'wrong')::int,1,'wrong is evidence based');
select is((pg_temp.report()->'summary'->>'blank')::int,1,'blank is evidence based');
select is(jsonb_array_length(pg_temp.report()->'topics'),4,'same topic stays separate by grade and program including unknown program');
select is((pg_temp.report(30,6)->'summary'->>'total')::int,1,'grade filter is exact');
select is((public.learning_progress('00000000-0000-4000-8000-000000003621',30,'Fen')->'summary'->>'total')::int,0,'empty subject does not borrow other subjects');
select is((select sum((w->>'total')::int)::int from jsonb_array_elements(pg_temp.report()->'weeks') w),9,'weekly totals reconcile to summary');
select is((select sum((w->>'pending')::int)::int from jsonb_array_elements(pg_temp.report()->'weeks') w),1,'pending separate from chart scores');
select is((select sum((t->>'total')::int)::int from jsonb_array_elements(pg_temp.report()->'topics') t),9,'topic totals reconcile');
select is((select count(*)::int from jsonb_array_elements(pg_temp.report()->'topics') t where t->'curriculum'='null'),1,'unknown program remains explicit');
select ok((select bool_and((t->>'limited_observation')::boolean) from jsonb_array_elements(pg_temp.report(30,6)->'topics') t),'small sample is not a skill judgement');
select is((select count(*)::int from jsonb_array_elements(pg_temp.report()->'topics') t, jsonb_array_elements(t->'evidence') e where e->>'state'='pending'),1,'pending evidence remains reachable in review queue');
select is(pg_temp.report()->>'from',((now() at time zone 'Europe/Istanbul')::date-29)::text,'report starts on a family-local calendar day');
select is(pg_temp.report()->>'through',((now() at time zone 'Europe/Istanbul')::date)::text,'report ends on family-local today');
